package africa.growtogether.platform.ewe.task; import java.time.Instant; import java.util.UUID; public final class TaskDtos {private TaskDtos(){} public record CreateTask(UUID instanceId,String taskKey,String name,TaskType taskType,AssignmentType assignmentType,String assignmentValue,Instant dueAt,Instant escalationAt){} public record CompleteTask(String outcome,String comment){} public record Decision(ApprovalDecision decision,String comment){} public record Delegate(UUID fromUserId,UUID toUserId){} public record CreateRoutingRule(UUID workflowDefinitionId,String taskKey,int priority,String conditionExpression,AssignmentType assignmentType,String assignmentValue){} public record TaskView(UUID id,UUID instanceId,String taskKey,String name,TaskType type,TaskStatus status,AssignmentType assignmentType,UUID assigneeUserId,String assigneeRole,String assigneeGroup,String routingExpression,UUID claimedBy,Instant dueAt,Instant escalationAt,Instant completedAt,String outcome){public static TaskView from(WorkflowTask t){return new TaskView(t.getId(),t.getInstanceId(),t.getTaskKey(),t.getName(),t.getTaskType(),t.getTaskStatus(),t.getAssignmentType(),t.getAssigneeUserId(),t.getAssigneeRole(),t.getAssigneeGroup(),t.getRoutingExpression(),t.getClaimedBy(),t.getDueAt(),t.getEscalationAt(),t.getCompletedAt(),t.getOutcome());}} }